<script lang="ts">
export default {options:{styleIsolation:'shared'}}
</script>
<script setup lang="ts">
import DecorationAction from './DecorationAction.vue'
import {computed,ref,onMounted,nextTick,watch,getCurrentInstance} from 'vue'
import {decorationUnitStyle} from '@qicore/application-sdk/browser/decoration-components.mjs'
import type {DecorationBlock,DecorationLink} from '@qicore/application-sdk/browser/decoration-types'
import {decorationOptions,noticeItems,decorationLabelStyle} from '@qicore/application-sdk/browser/decoration-options.mjs'
const props=defineProps<{block:DecorationBlock;images:Record<string,string>;primary:string}>()
const emit=defineEmits<{navigate:[target:DecorationLink]}>()
const o=computed(()=>decorationOptions(props.block)),items=computed(()=>noticeItems(props.block)),message=ref(''),popup=ref(false),overflow=ref(false),duration=ref(3000),instance=getCurrentInstance()
function measure(){nextTick(()=>{const query=uni.createSelectorQuery().in(instance);query.select('.notice-window').boundingClientRect();query.select('.marquee-line').boundingClientRect();query.exec((result:any[])=>{if(result[0]&&result[1]){overflow.value=result[0].width<result[1].width-30;duration.value=Math.ceil(result[1].width*14)}})})}
onMounted(measure);watch(()=>[props.block.items,props.block.options],measure,{deep:true})
function activate(index:number){const item=items.value[index];if(!item)return;if(o.value.noticeAction==='link')emit('navigate',item.target);else{message.value=item.text||item.label;popup.value=true}}
</script>
<template><view class="notice qc-view"><image v-if="o.noticeMode==='image'" class="notice-image qc-image" :src="o.noticePreset==='custom'&&o.noticeImageId&&images[o.noticeImageId]?images[o.noticeImageId]:'/static/decoration/notice-'+(o.noticePreset==='style1'?1:2)+'.png'" mode="aspectFit"/><text v-else class="notice-badge qc-text" :style="{color:primary,background:primary+'12'}">{{block.title||'公告'}}</text><swiper v-if="o.noticeScroll==='vertical'" class="notice-window qc-swiper" vertical :autoplay="items.length>1" :circular="items.length>1" :duration="500" :interval="3000"><swiper-item v-for="(item,index) in items" :key="item.id" class="qc-swiper-item"><DecorationAction :target="o.noticeAction==='link'?item.target:''" root-class="notice-text" :root-style="decorationUnitStyle(decorationLabelStyle(block),true)" @click="activate(index)">{{item.text||item.label}}</DecorationAction></swiper-item></swiper><view v-else class="notice-window qc-view"><view class="notice-marquee qc-view" :style="{animation:overflow?'':'none',animationDuration:duration+'ms'}"><view class="marquee-line qc-view"><DecorationAction :target="o.noticeAction==='link'?item.target:''" root-class="notice-action" v-for="(item,index) in items" :key="item.id" :root-style="decorationLabelStyle(block)" @click="activate(index)">{{item.text||item.label}}</DecorationAction></view><view v-if="overflow" class="marquee-line qc-view"><DecorationAction :target="o.noticeAction==='link'?item.target:''" root-class="notice-action" v-for="(item,index) in items" :key="item.id" :root-style="decorationLabelStyle(block)" @click="activate(index)">{{item.text||item.label}}</DecorationAction></view></view></view><image v-if="o.noticeScroll==='vertical'" class="notice-arrow qc-image" src="/static/decoration/chevron-right.svg"/></view><view v-if="popup" class="notice-overlay qc-view" @click="popup=false"><view class="notice-popup qc-view" @click.stop><text class="notice-popup-title qc-text">公告</text><scroll-view enhanced scroll-y class="notice-popup-body qc-scroll-view" :show-scrollbar="false"><text class="qc-text">{{message}}</text></scroll-view><button :style="{background:primary}" @click="popup=false" class="qc-button">我知道了</button></view></view></template>
<style scoped>.notice{display:flex;align-items:center;gap:20rpx;min-height:48rpx;padding:22rpx 22rpx 22rpx 28rpx;box-sizing:border-box}.notice-image{height:40rpx;width:200rpx;flex-shrink:0}.notice-badge{max-width:128rpx;padding:0 12rpx;height:40rpx;line-height:40rpx;border-radius:8rpx;font-size:26rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex-shrink:0}.notice-window{height:48rpx;flex:1;min-width:0;overflow:hidden}.notice-text{display:block;width:100%;height:48rpx;line-height:48rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.notice-arrow{width:26rpx;height:26rpx;flex-shrink:0}.notice-marquee{display:flex;align-items:center;width:max-content;height:48rpx;animation:notice-marquee 18s linear infinite;animation-delay:800ms}.marquee-line{display:flex;gap:80rpx;padding-right:80rpx;flex-shrink:0}.marquee-line>.qc-text{white-space:nowrap}.notice-overlay{position:fixed;inset:0;z-index:1000;background:#0006;display:flex;align-items:center;justify-content:center}.notice-popup{width:570rpx;padding:44rpx 32rpx;border-radius:28rpx;background:#fff;color:#303133}.notice-popup-title{display:block;text-align:center;font-size:34rpx;font-weight:600;margin-bottom:40rpx}.notice-popup-body{height:260rpx;white-space:pre-wrap;font-size:28rpx;line-height:1.7}.notice-popup .qc-button{height:70rpx;line-height:70rpx;margin-top:40rpx;border-radius:36rpx;color:white;font-size:26rpx;border:0}.notice-popup .qc-button::after{border:0}@keyframes notice-marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}</style>

<style scoped>.notice-action{display:inline-block;white-space:nowrap}</style>
